def _sort(rows):
    return sorted(rows, key=lambda row: row["id"])


def _forward_sort(rows):
    return _sort(rows)


def load_records(payload):
    if "rows" in payload:
        return _forward_sort(payload["rows"])
    return _forward_sort(payload["records"])

